  function showRestrictionNotice(profile,sanction,issuer){const banned=profile.status==="banned",suspended=profile.status==="suspended",pending=profile.status==="pending",notice=$("restrictionNotice");if(!notice)return;clearInterval(restrictionTimer);$("restrictionDisputeForm").reset();$("restrictionDisputeForm").classList.remove("hidden");$("restrictionDisputeState").classList.add("hidden");$("rolePill").textContent="Accès restreint";$("restrictionTitle").textContent=banned?"Compte banni définitivement":suspended?"Compte suspendu":pending?"Compte en attente de validation":"Accès au compte limité";$("restrictionSummary").textContent=banned?"La connexion à ton espace DevReports est désactivée par l’administration.":suspended?"La connexion à ton espace DevReports est temporairement suspendue.":"Ton compte n’a pas encore été accepté par l’administration.";$("restrictionIssuer").textContent=issuer||"Administration";$("restrictionReason").textContent=sanction?.action==="ban"?"Bannissement définitif":sanction?.action==="suspend"?"Suspension temporaire":pending?"Demande d’accès en attente":"Restriction du compte";const expiry=sanction?.expires_at||profile.suspended_until,remainingWrap=$("restrictionRemainingWrap");remainingWrap.classList.toggle("hidden",banned||pending||!expiry);$("restrictionRemaining").textContent=expiry?formatRemaining(expiry):"Réactivation manuelle par un administrateur";if(suspended&&!expiry){remainingWrap.classList.remove("hidden");$("restrictionRemaining").textContent="Jusqu’à réactivation par un administrateur"}$("restrictionDescription").textContent=sanction?.reason||profile.restriction_reason||"Aucune description n’a été indiquée.";const disputeArea=$("restrictionDisputeArea");disputeArea.classList.toggle("hidden",!(sanction?.id&&(banned||suspended)));if(sanction?.id&&(banned||suspended)){db.from("sanction_disputes").select("id,status").eq("sanction_id",sanction.id).eq("member_id",currentUser.id).eq("status","open").limit(1).maybeSingle().then(({data,error})=>{if(!error&&data){$("restrictionDisputeForm").classList.add("hidden");$("restrictionDisputeState").textContent="Ta contestation a bien été envoyée. Elle est en attente d’examen par l’administration.";$("restrictionDisputeState").classList.remove("hidden")}});$("restrictionDisputeForm").onsubmit=async event=>{event.preventDefault();const form=event.currentTarget,reason=$("restrictionDisputeReason").value.trim(),submit=form.querySelector('[type="submit"]');if(reason.length<3)return toast("Ajoute quelques détails à ta contestation.",true);submit.disabled=true;const {error}=await db.from("sanction_disputes").insert({sanction_id:sanction.id,member_id:currentUser.id,reason});submit.disabled=false;if(error)return toast(error.code==="23505"?"Une contestation est déjà en attente.":"Envoi impossible : "+error.message,true);form.classList.add("hidden");$("restrictionDisputeState").textContent="Ta contestation a bien été envoyée. Elle est en attente d’examen par l’administration.";$("restrictionDisputeState").classList.remove("hidden");toast("Contestation transmise à l’administration.")}}notice.classList.remove("hidden");notice.scrollIntoView({behavior:"smooth",block:"start"});if(suspended&&expiry)restrictionTimer=setInterval(()=>{$("restrictionRemaining").textContent=formatRemaining(expiry)},60000)}
  function weekAgo(s){return new Date(s).getTime()>=Date.now()-7*86400000;}
