  async function loadProfile(){
    const {data,error}=await db.from("profiles").select("display_name,nickname,role,status,roles,suspended_until,restriction_reason,created_at").eq("id",currentUser.id).single();
    if(error) throw error; currentProfile=data;
  }
  async function fetchAllRows(table,columns="*",orderColumn="created_at"){
    const rows=[],pageSize=500;let start=0;
    while(true){let query=db.from(table).select(columns);if(orderColumn)query=query.order(orderColumn,{ascending:false}).order("id",{ascending:true});const {data,error}=await query.range(start,start+pageSize-1);if(error)throw error;const batch=data||[];rows.push(...batch);if(batch.length<pageSize)break;start+=pageSize}
    return rows;
  }
  async function refreshReports(){
    const [data,profiles,roles]=await Promise.all([
      fetchAllRows("reports","id,user_id,project,category,version,title,work,issues,next_steps,author_roles,action_types,report_type,platform,moderation_action,moderated_user,discord_server,discord_area,discord_target,discord_changes,created_at"),
      fetchAllRows("profiles","id,display_name,nickname,role,roles,status,suspended_until,restriction_reason,created_at"),
      fetchAllRows("team_roles","role_key,label",null)
    ]);
    allProfiles=profiles;
    allTeamRoles=roles.sort((a,b)=>a.label.localeCompare(b.label,"fr"));
    syncReportRoleOptions();
    const names=new Map(profiles.map(p=>[p.id,p.nickname||p.display_name]));
    if(currentUser&&currentProfile)names.set(currentUser.id,currentProfile.display_name);
    allReports=data.map(r=>({...r,profiles:{display_name:names.get(r.user_id)||"Membre"}}));
    const filter=$("personFilter");if(filter){const selected=filter.value;filter.innerHTML='<option value="">Toute l’équipe</option>'+allProfiles.filter(p=>p.status==="active").map(p=>`<option value="${escapeHtml(p.id)}">${escapeHtml(p.display_name)}</option>`).join("");filter.value=selected}
    renderReports();renderStats();if(currentProfile?.role==="admin")renderTeam();if(!$('presencePage').classList.contains('hidden'))loadPresencePage();if(!$('messagesPage').classList.contains('hidden'))loadMessages();
  }
  function roleLabel(key){return allTeamRoles.find(role=>role.role_key===key)?.label||key}
  function roleLabels(keys){return (keys||[]).map(roleLabel).join(" · ")||"Non précisés"}
  function primaryAdminId(){return allProfiles.filter(profile=>profile.role==="admin").sort((a,b)=>new Date(a.created_at)-new Date(b.created_at))[0]?.id||null}
  function isPrimaryAdmin(){return currentUser?.id===primaryAdminId()}
