    if(!project||!title||!work)return toast("Projet, titre et travaux réalisés sont obligatoires.",true);
    const payload={user_id:currentUser.id,project,category:$("category").value,version:$("version").value.trim(),title,work,issues:$("issues").value.trim(),next_steps:$("next").value.trim(),author_roles:Array.from(document.querySelectorAll('#reportRoles input:checked')).map(x=>x.value),action_types:Array.from(document.querySelectorAll('#actionTypes input:checked')).map(x=>x.value)};
