  function renderAbsenceCard(row,adminView=false){const owner=allProfiles.find(p=>p.id===row.user_id),status=presenceStatusLabel(row.status,'absence');return `<article class="presence-item"><div class="presence-item-head"><div><strong>${escapeHtml(adminView?(owner?.nickname||owner?.display_name||'Membre'):'Absence')}</strong><span class="status-chip status-${escapeHtml(row.status)}">${status}</span></div><span class="muted">${dateOnlyLabel(row.start_date)}${row.end_date!==row.start_date?' → '+dateOnlyLabel(row.end_date):''}</span></div><p>${escapeHtml(row.reason)}</p>${row.admin_note?`<div class="presence-note">Note admin · ${escapeHtml(row.admin_note)}</div>`:''}${adminView&&row.status==='pending'?`<div class="presence-actions"><button class="btn" data-absence-review="approved" data-presence-id="${row.id}">Approuver</button><button class="btn danger" data-absence-review="rejected" data-presence-id="${row.id}">Refuser</button></div>`:''}</article>`}
  function renderLateCard(row,adminView=false){const owner=allProfiles.find(p=>p.id===row.user_id);return `<article class="presence-item"><div class="presence-item-head"><div><strong>${escapeHtml(adminView?(owner?.nickname||owner?.display_name||'Membre'):'Retard')}</strong><span class="status-chip status-${escapeHtml(row.status)}">${presenceStatusLabel(row.status,'late')}</span></div><span class="muted">${new Date(row.session_at).toLocaleString('fr-FR',{dateStyle:'medium',timeStyle:'short'})}</span></div><p>Retard estimé : <strong>${Number(row.expected_delay_minutes)} min</strong></p><p>${escapeHtml(row.reason)}</p>${row.admin_note?`<div class="presence-note">Note admin · ${escapeHtml(row.admin_note)}</div>`:''}${adminView&&row.status==='pending'?`<div class="presence-actions"><button class="btn secondary" data-late-review="acknowledged" data-presence-id="${row.id}">Marquer pris en compte</button></div>`:''}</article>`}
  async function loadPresencePage(){const admin=currentProfile?.role==='admin';$('adminPresenceReview').classList.toggle('hidden',!admin);const [ownAbs,ownLate]=await Promise.all([db.from('team_absences').select('id,user_id,start_date,end_date,reason,status,admin_note,created_at').eq('user_id',currentUser.id).order('created_at',{ascending:false}).limit(30),db.from('late_notices').select('id,user_id,session_at,expected_delay_minutes,reason,status,admin_note,created_at').eq('user_id',currentUser.id).order('created_at',{ascending:false}).limit(30)]);if(ownAbs.error||ownLate.error){$('myAbsences').innerHTML='<div class="empty">Impossible de charger le suivi. L’administrateur doit appliquer la dernière version de supabase_setup.sql.</div>';$('myLateNotices').innerHTML='';if(admin){$('teamAbsences').innerHTML='';$('teamLateNotices').innerHTML=''}return}const absences=ownAbs.data||[],late=ownLate.data||[];$('myAbsences').innerHTML=absences.map(row=>renderAbsenceCard(row)).join('')||'<div class="empty">Aucun signalement d’absence.</div>';$('myLateNotices').innerHTML=late.map(row=>renderLateCard(row)).join('')||'<div class="empty">Aucun retard signalé.</div>';if(!admin)return;const [teamAbs,teamLate]=await Promise.all([db.from('team_absences').select('id,user_id,start_date,end_date,reason,status,admin_note,created_at').order('created_at',{ascending:false}).limit(100),db.from('late_notices').select('id,user_id,session_at,expected_delay_minutes,reason,status,admin_note,created_at').order('created_at',{ascending:false}).limit(100)]);if(teamAbs.error||teamLate.error){$('teamAbsences').innerHTML='<div class="empty">Suivi admin indisponible. Vérifie les règles RLS Supabase.</div>';return}const teamAbsences=teamAbs.data||[],teamLateRows=teamLate.data||[];$('teamAbsences').innerHTML=teamAbsences.map(row=>renderAbsenceCard(row,true)).join('')||'<div class="empty">Aucune absence.</div>';$('teamLateNotices').innerHTML=teamLateRows.map(row=>renderLateCard(row,true)).join('')||'<div class="empty">Aucun retard signalé.</div>';document.querySelectorAll('[data-absence-review]').forEach(button=>button.onclick=async()=>{const {error}=await db.from('team_absences').update({status:button.dataset.absenceReview,reviewed_by:currentUser.id,reviewed_at:new Date().toISOString()}).eq('id',button.dataset.presenceId).eq('status','pending');if(error)return toast('Impossible de traiter cette demande : '+error.message,true);toast(button.dataset.absenceReview==='approved'?'Absence approuvée.':'Demande refusée.');loadPresencePage()});document.querySelectorAll('[data-late-review]').forEach(button=>button.onclick=async()=>{const {error}=await db.from('late_notices').update({status:'acknowledged',reviewed_by:currentUser.id,reviewed_at:new Date().toISOString()}).eq('id',button.dataset.presenceId).eq('status','pending');if(error)return toast('Impossible de traiter ce retard : '+error.message,true);toast('Retard marqué comme pris en compte.');loadPresencePage()})}
  $('absenceStart').min=localDateInputValue();$('absenceEnd').min=localDateInputValue();$('absenceStart').onchange=()=>{$('absenceEnd').min=$('absenceStart').value||localDateInputValue();if($('absenceEnd').value&&$('absenceEnd').value<$('absenceStart').value)$('absenceEnd').value=$('absenceStart').value};$('lateSession').min=localDateTimeInputValue();
  $('absenceForm').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget,start_date=$('absenceStart').value,end_date=$('absenceEnd').value,reason=$('absenceReason').value.trim();if(!start_date||!end_date||end_date<start_date||reason.length<3)return toast('Vérifie les dates et indique un motif suffisamment précis.',true);const {error}=await db.from('team_absences').insert({user_id:currentUser.id,start_date,end_date,reason});if(error)return toast('Envoi impossible : '+error.message,true);form.reset();$('absenceStart').min=localDateInputValue();$('absenceEnd').min=localDateInputValue();toast('Demande d’absence envoyée aux administrateurs.');loadPresencePage()};
  $('lateForm').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget,localValue=$('lateSession').value,minutes=Number($('lateMinutes').value),reason=$('lateReason').value.trim();if(!localValue||!Number.isInteger(minutes)||minutes<1||minutes>1440||reason.length<3)return toast('Renseigne l’heure, une durée entre 1 et 1440 minutes et un motif.',true);const {error}=await db.from('late_notices').insert({user_id:currentUser.id,session_at:new Date(localValue).toISOString(),expected_delay_minutes:minutes,reason});if(error)return toast('Envoi impossible : '+error.message,true);form.reset();$('lateSession').min=localDateTimeInputValue();toast('Retard signalé à l’équipe.');loadPresencePage()};
  async function loadMessages(){const pane=$('teamMessages');if(!pane||!currentUser)return;const wasAtBottom=pane.scrollHeight-pane.scrollTop-pane.clientHeight<90;const {data,error}=await db.from('team_messages').select('id,user_id,body,created_at').order('created_at',{ascending:false}).limit(100);if(error){pane.innerHTML='<div class="empty">Messagerie inaccessible. Vérifie que la migration SQL est appliquée et que ton compte est actif.</div>';return}const rows=(data||[]).reverse();pane.innerHTML=rows.map(message=>{const profile=allProfiles.find(item=>item.id===message.user_id),mine=message.user_id===currentUser.id;return `<article class="chat-message ${mine?'mine':''}"><div class="chat-message-meta"><strong>${escapeHtml(profile?.nickname||profile?.display_name||(mine?currentProfile?.display_name:'Membre'))}</strong><time datetime="${escapeHtml(message.created_at)}">${new Date(message.created_at).toLocaleString('fr-FR',{dateStyle:'short',timeStyle:'short'})}</time></div><p>${escapeHtml(message.body)}</p></article>`}).join('')||'<div class="empty">Pas encore de message. Lance la discussion avec l’équipe.</div>';if(wasAtBottom||rows.at(-1)?.user_id===currentUser.id)pane.scrollTop=pane.scrollHeight}
  function connectTeamMessages(){if(teamMessageChannel||!db)return;teamMessageChannel=db.channel('team-messages').on('postgres_changes',{event:'INSERT',schema:'public',table:'team_messages'},()=>{if(!$('messagesPage').classList.contains('hidden'))loadMessages()}).subscribe(status=>{$('chatConnectionState').textContent=status==='SUBSCRIBED'?'En direct':status==='CHANNEL_ERROR'?'Actualisation automatique':'Connexion…'});if(!teamMessagePoll)teamMessagePoll=setInterval(()=>{if(currentUser&&!$('messagesPage').classList.contains('hidden'))loadMessages()},12000)}
  function disconnectTeamMessages(){if(teamMessagePoll){clearInterval(teamMessagePoll);teamMessagePoll=null}if(teamMessageChannel&&db){db.removeChannel(teamMessageChannel);teamMessageChannel=null}}
  $('messageForm').onsubmit=async event=>{event.preventDefault();const input=$('messageBody'),body=input.value.trim();if(!body)return toast('Écris un message avant de l’envoyer.',true);if(body.length>2000)return toast('Le message dépasse 2000 caractères.',true);const button=event.submitter;button.disabled=true;const {error}=await db.from('team_messages').insert({user_id:currentUser.id,body});button.disabled=false;if(error)return toast('Message non envoyé : '+error.message,true);input.value='';await loadMessages();input.focus()};
  async function loadMyWarnings(){const panel=$("memberWarningsPanel");if(!panel)return;panel.classList.toggle("hidden",currentProfile?.role==="admin");if(currentProfile?.role==="admin")return;const {data,error}=await db.from("member_warnings").select("id,motif,description,reason,admin_name,created_at").eq("member_id",currentUser.id).order("created_at",{ascending:false});if(error){$("myWarnings").innerHTML='<div class="empty">Impossible de charger tes avertissements. L’administrateur doit appliquer la migration de <strong>supabase_setup.sql</strong> dans le SQL Editor Supabase.</div>';return}const warnings=data||[],disputesResult=await db.from("warning_disputes").select("warning_id,status").eq("user_id",currentUser.id),disputeMap=new Map((disputesResult.data||[]).map(item=>[item.warning_id,item.status]));$("myWarnings").innerHTML=warnings.map((w,index)=>warningCard(w,"Pour toi",w.admin_name||"Administration",false,index,disputeMap.get(w.id)||null)).join("")||'<div class="empty">Aucun avertissement ne t’a été attribué.</div>';document.querySelectorAll("[data-contest-warning]").forEach(button=>button.onclick=async()=>{const reason=await siteDialog({title:"Contester cet avertissement",message:"Explique calmement pourquoi tu contestes ce warn. Ta demande sera transmise à l’administration.",placeholder:"Ta contestation…",confirmText:"Envoyer la contestation",textarea:true});if(!reason?.trim())return;const {error}=await db.from("warning_disputes").insert({warning_id:button.dataset.contestWarning,user_id:currentUser.id,reason:reason.trim()});if(error)return toast("Contestation non envoyée : "+error.message,true);toast("Ta contestation a été envoyée à l’administration.");loadMyWarnings()})}
  async function loadWarningDisputes(warnings=[]){const container=$("warningDisputesList");if(!container)return;const {data,error}=await db.from("warning_disputes").select("id,warning_id,user_id,reason,status,created_at").order("created_at",{ascending:false});if(error){container.innerHTML='<div class="empty">Impossible de charger les contestations. Applique la migration SQL Supabase.</div>';return}const rows=data||[];container.innerHTML=rows.map(d=>{const member=allProfiles.find(p=>p.id===d.user_id)?.display_name||"Membre",warning=warnings.find(w=>w.id===d.warning_id),state=d.status==="open"?"En attente":d.status==="reviewed"?"Examinée":"Classée";return `<article class="warning-card"><div class="warning-card-head"><div><h3>Contestation · ${escapeHtml(warning?.motif||"Avertissement")}</h3><div class="warning-meta">Par <strong>${escapeHtml(member)}</strong> · ${dateLabel(d.created_at)}</div></div><span class="pill">${state}</span></div><p class="dispute-summary">${escapeHtml(d.reason)}</p>${d.status==="open"?`<div class="warning-actions"><button class="btn secondary" data-dispute-status="reviewed" data-dispute-id="${d.id}">Marquer examinée</button><button class="btn danger" data-dispute-status="dismissed" data-dispute-id="${d.id}">Classer</button></div>`:""}</article>`}).join("")||'<div class="empty">Aucune contestation reçue.</div>';document.querySelectorAll("[data-dispute-id]").forEach(button=>button.onclick=async()=>{const {error}=await db.from("warning_disputes").update({status:button.dataset.disputeStatus}).eq("id",button.dataset.disputeId);if(error)return toast(error.message,true);toast("Statut de la contestation mis à jour.");loadWarningDisputes(warnings)})}
  async function loadAllDisputes(){const container=$("allDisputesList");if(!container||currentProfile?.role!=="admin")return;container.innerHTML='<div class="empty">Chargement des contestations…</div>';const [warnings,sanctions]=await Promise.all([db.from("warning_disputes").select("id,warning_id,user_id,reason,status,created_at").order("created_at",{ascending:false}).limit(100),db.from("sanction_disputes").select("id,sanction_id,member_id,reason,status,created_at,admin_note").order("created_at",{ascending:false}).limit(100)]);const rows=[];for(const row of warnings.data||[])rows.push({...row,kind:"warning",member:allProfiles.find(p=>p.id===row.user_id)?.nickname||allProfiles.find(p=>p.id===row.user_id)?.display_name||"Membre",title:"Avertissement contesté"});for(const row of sanctions.data||[])rows.push({...row,kind:"sanction",member:allProfiles.find(p=>p.id===row.member_id)?.nickname||allProfiles.find(p=>p.id===row.member_id)?.display_name||"Membre",title:"Suspension / bannissement contesté"});rows.sort((a,b)=>new Date(b.created_at)-new Date(a.created_at));const open=rows.filter(row=>row.status==="open").length;$("teamDisputesCount").textContent=open?`· ${open}`:"";container.innerHTML=[...warnings.error?[`<div class="empty">Avertissements : ${escapeHtml(warnings.error.message)}</div>`]:[],...sanctions.error?[`<div class="empty">Sanctions : ${escapeHtml(sanctions.error.message)}. Applique la mise à jour SQL.</div>`]:[],...rows.map(row=>{const state=row.status==="open"?"En attente":row.status==="accepted"?"Acceptée":row.status==="dismissed"?"Refusée":"Examinée";const actions=row.status!=="open"?"":row.kind==="sanction"?`<div class="warning-actions"><button class="btn" data-resolve-dispute="accepted" data-dispute-kind="sanction" data-dispute-id="${row.id}" data-member-id="${row.member_id}">Accepter et rétablir l’accès</button><button class="btn danger" data-resolve-dispute="dismissed" data-dispute-kind="sanction" data-dispute-id="${row.id}">Refuser</button></div>`:`<div class="warning-actions"><button class="btn secondary" data-resolve-dispute="reviewed" data-dispute-kind="${row.kind}" data-dispute-id="${row.id}">Marquer examinée</button><button class="btn danger" data-resolve-dispute="dismissed" data-dispute-kind="${row.kind}" data-dispute-id="${row.id}">Classer</button></div>`;return `<article class="warning-card dispute-card"><div class="warning-card-head"><div><span class="dispute-type dispute-${row.kind}">${row.kind==="warning"?"WARN":"SANCTION"}</span><h3>${escapeHtml(row.title)}</h3><div class="warning-meta">De <strong>${escapeHtml(row.member)}</strong> · ${dateLabel(row.created_at)}</div></div><span class="pill">${state}</span></div><p class="dispute-summary">${escapeHtml(row.reason)}</p>${row.admin_note?`<p class="muted">Note admin : ${escapeHtml(row.admin_note)}</p>`:""}${actions}</article>`}).join("")].join("")||'<div class="empty">Aucune contestation pour le moment.</div>';container.querySelectorAll("[data-resolve-dispute]").forEach(button=>button.onclick=async()=>{const kind=button.dataset.disputeKind,status=button.dataset.resolveDispute;button.disabled=true;let error=null;if(kind==="sanction"&&status==="accepted"){const restored=await db.from("profiles").update({status:"active",suspended_until:null,restriction_reason:""}).eq("id",button.dataset.memberId);error=restored.error}if(!error&&kind==="sanction"){const result=await db.from("sanction_disputes").update({status,reviewed_by:currentUser.id,reviewed_at:new Date().toISOString()}).eq("id",button.dataset.disputeId);error=result.error}else if(!error){const table="warning_disputes",result=await db.from(table).update({status}).eq("id",button.dataset.disputeId);error=result.error}if(error){button.disabled=false;return toast("Impossible de traiter la contestation : "+error.message,true)}toast(status==="accepted"?"Contestation acceptée, accès rétabli.":status==="dismissed"?"Contestation classée.":"Contestation marquée examinée.");await refreshReports();loadAllDisputes()})}
  $("sendWarn").onclick=async()=>{const member_id=$("warnMember").value,motif=$("warnMotif").value,description=$("warnDescription").value.trim();if(!member_id||!description)return toast("Choisis un membre et décris les faits.",true);const {error}=await db.from("member_warnings").insert({member_id,admin_id:currentUser.id,admin_name:currentProfile.display_name||currentUser.email,motif,description,reason:description});if(error)return toast(error.message,true);$("warnDescription").value="";toast("Avertissement enregistré.");loadTeamWarnings()};
